import * as Effect from "effect/Effect";
import { OrchestrationV2DispatchCommandError, OrchestrationV2ThreadLaunchError } from "@t3tools/contracts";
import * as ThreadManagementService from "./ThreadManagementService.session-api.ts";
import * as ThreadMessageIntake from "./ThreadMessageIntake.ts";
import { projectThreadProjectionForWire } from "./WireProjection.ts";
import { userFacingDispatchErrorMessage } from "./UserFacingErrors.ts";
import type { OrchestrationV2Command, OrchestrationV2ThreadLaunchInput, OrchestrationV2ThreadLaunchResult, OrchestrationV2DispatchCommandResult } from "@t3tools/contracts";
import type { ThreadManagementProvenance } from "./ThreadManagementService.session-api.ts";
import * as ThreadLaunch from "./ThreadLaunchService.ts";

export const dispatchCommand = (command: OrchestrationV2Command, provenance: ThreadManagementProvenance): Effect.Effect<OrchestrationV2DispatchCommandResult, OrchestrationV2DispatchCommandError, Services<ReturnType<typeof ThreadMessageIntake.dispatchCommand>> | ThreadLaunch.ThreadLaunchService> => Effect.gen(function* () {
  const threadLaunch = yield* ThreadLaunch.ThreadLaunchService;
  return yield*

import { type ProjectId, ScheduledTaskError, ThreadId, ScheduledTaskWebhookDeliveryId, type ScheduledTaskDeleteInput, type ScheduledTaskDeleteResult, type ScheduledTaskGetWebhookDeliveryInput, type ScheduledTaskGetWebhookDeliveryResult, type ScheduledTaskListWebhookDeliveriesInput, type ScheduledTaskListWebhookDeliveriesResult, type ScheduledTaskRotateWebhookTokenInput, type ScheduledTaskListResult, type ScheduledTaskMutationResult, type ScheduledTaskRunNowInput, type ScheduledTaskRunNowResult, type ScheduledTaskSetEnabledInput, type ScheduledTaskUpsertInput } from "@t3tools/contracts";
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { type WebhookRequest } from "./webhookTemplate.ts";

